/* ==========================================================================
   KAÏRO CONSOLE — FLOO EDITION
   Thème haut de gamme pour expérience TV / Manette
   ========================================================================== */

/* Conteneur principal */
.kairo-console-launcher {
  background: radial-gradient(circle at 80% 20%, rgba(244, 63, 94, 0.08) 0%, transparent 50%),
              radial-gradient(circle at 20% 80%, rgba(56, 189, 248, 0.05) 0%, transparent 50%),
              #080c14 !important;
}

/* Topbar discrète type console */
.kairo-launcher-topbar {
  padding: 24px 40px !important;
}

/* Hero zone : grand titre percutant */
.kairo-hero-title {
  font-size: clamp(2rem, 4vw, 3.2rem) !important;
  font-weight: 900 !important;
  letter-spacing: -0.02em !important;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.8) !important;
  text-transform: uppercase !important;
}

/* Métadonnées épurées avec séparateurs lisibles */
.kairo-hero-meta {
  font-size: 1.05rem !important;
  font-weight: 600 !important;
  letter-spacing: 0.05em !important;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.7) !important;
}

/* Bouton principal Jouer [A] avec halo rose signature */
.kairo-hero-btn-play {
  background: linear-gradient(135deg, #f43f5e 0%, #e11d48 100%) !important;
  border-radius: 12px !important;
  padding: 12px 28px !important;
  font-weight: 800 !important;
  letter-spacing: 0.06em !important;
  box-shadow: 0 8px 24px -4px rgba(244, 63, 94, 0.6), 0 0 16px rgba(244, 63, 94, 0.3) !important;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease !important;
}

.kairo-hero-btn-play:hover,
.kairo-hero-btn-play:focus-visible {
  transform: translateY(-2px) scale(1.03) !important;
  box-shadow: 0 12px 28px -4px rgba(244, 63, 94, 0.75), 0 0 24px rgba(244, 63, 94, 0.45) !important;
}

/* Boutons secondaires en verre sombre [X] et [Y] */
.kairo-hero-btn-action {
  background: rgba(255, 255, 255, 0.08) !important;
  backdrop-filter: blur(16px) !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  border-radius: 12px !important;
  padding: 10px 20px !important;
  font-weight: 700 !important;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.kairo-hero-btn-action:hover,
.kairo-hero-btn-action:focus-visible {
  background: rgba(255, 255, 255, 0.16) !important;
  border-color: rgba(255, 255, 255, 0.3) !important;
  transform: translateY(-2px) !important;
}

/* Carrousel : disposition aérée */
.kairo-carousel {
  padding: 20px 40px 30px 40px !important;
  gap: 20px !important;
}

/* Cartes non focalisées : élégantes et subtilement atténuées */
.kairo-carousel-card {
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1) !important;
  border: 2px solid rgba(255, 255, 255, 0.1) !important;
  opacity: 0.85;
}

.kairo-carousel-card:hover {
  opacity: 0.95;
  border-color: rgba(255, 255, 255, 0.25) !important;
}

/* Carte active focalisée : mise en avant avec bordure rose Kaïro et élévation */
.kairo-carousel-card-focused,
.kairo-carousel-card[data-active="true"] {
  opacity: 1 !important;
  transform: translateY(-8px) scale(1.05) !important;
  border-color: #f43f5e !important;
  border-width: 2.5px !important;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.85),
              0 0 24px rgba(244, 63, 94, 0.55),
              0 0 45px rgba(244, 63, 94, 0.25) !important;
  z-index: 10 !important;
}

/* Barre d'aide manette inférieure (Bottom Bar) */
.kairo-controller-bar {
  background: rgba(8, 12, 20, 0.85) !important;
  backdrop-filter: blur(20px) !important;
  border-top: 1px solid rgba(255, 255, 255, 0.08) !important;
  padding: 14px 40px !important;
  font-size: 0.85rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.05em !important;
}
